(* UCodeShP.v -- the CODE CATALOG of the user program [shp].
   AUTO-GENERATED by tools/gen_ucode.py.  DO NOT EDIT BY HAND.

   Regenerate the whole layer with `make gen-ucode`; `make check-ucode`
   regenerates and then FAILS if anything moved.  This file alone is

     tools/gen_ucode.py --module Sh --prog shp --spec \
         tools/ucode_shp.txt --out iris/UCodeShP.v

   and WHICH instructions it covers is that spec file's to say. Edit the
   SPEC, never this output: a hand edit here is reverted, silently, by the
   next regeneration, and `make check-ucode` is what notices. Anything the
   generator cannot produce -- a predicate about the program's WRITABLE
   data half, say -- belongs in a hand-written file beside this one, not in
   it.

   The verified-user tier (claude-notes/projects/user-verified.md) drives
   one step from one [uinstr] fact (UmodeMem.v): the pure statement that at
   a given user pc the program's bytes sit in the process image [M], the
   pc's page is mapped fetch-executable, and the fetched word decodes to a
   named AST on any U-mode machine. This file proves those facts for the
   632 instruction(s) of this catalog, from the dumped image
   [User.ShInstrs.sh_bytes].

   Two premises carry every [uinstr] lemma:

     [shp_text_sub M]   -- [M] contains the dumped text (so a proof may talk
                          about a process image that ALSO has rodata, bss, a
                          stack page and an argument area in it);
     [shp_text_layout pt]
                       -- the pure page-table fact: each of the 2 page(s) of
                          the executable segment (0x0 .. 0x1fff) is mapped with a
                          leaf that permits instruction FETCH and a user data
                          LOAD.  The load half is not decoration: a program's
                          .rodata shares a text page and its string literals are
                          handed to [write]/[exec] as buffers.  The DATA page and
                          the heap are NOT this file's business -- they are
                          read-WRITE, and they, the stack and the argument area
                          belong to the program's own hand-written files
                          (UShp*.v / UkShp*.v), which is also where a predicate
                          over the writable half goes -- [UInitArgv.v] is the
                          worked example.

   Image geometry, as dumped:
     text  0x0 .. 0x1264   (4708 bytes)
     PT_LOAD 0x0      filesz 0x1c74   memsz 0x1c74   flags 5   (executable: 2 text page(s))
     PT_LOAD 0x2000   filesz 0x10     memsz 0x98     flags 6
     data  0x1264 .. 0x2010   (2592 bytes)
     entry 0x9ac, MemBase 0x0, MemEnd 0x2098

   Catalogued: 632 instruction(s), 379 distinct word(s), in 14 function(s):
     <parsecmd>       0x84a    .. 0x8ba       42 instr
     <parseline>      0x6be    .. 0x744       56 instr
     <parsepipe>      0x65e    .. 0x6bc       41 instr
     <parseexec>      0x56c    .. 0x65c       92 instr
     <parseredirs>    0x488    .. 0x56a       85 instr
     <nulterminate>   0x7ca    .. 0x848       50 instr
     <peek>           0x424    .. 0x486       40 instr
     <gettoken>       0x2ec    .. 0x422      104 instr
     <cmdalloc>       0x1d2    .. 0x206       23 instr
     <execcmd>        0x20a    .. 0x224       12 instr
     <redircmd>       0x226    .. 0x270       32 instr
     <pipecmd>        0x272    .. 0x29c       20 instr
     <strlen>         0xa0c    .. 0xa36       18 instr
     <strchr>         0xa5e    .. 0xa84       17 instr

   NOT catalogued, because no proof ever fetches it:
       panic -- already catalogued in iris/UCodeShK.v. Of the [panic] calls
       this walk crosses, parseexec's 'syntax' and 'too many args' are REFUTED
       (on a symbol-free line every token [gettoken] returns is 'a' or 0, and
       the argument count is bounded by the token list's length), and
       [cmdalloc]'s 'out of memory' is handed to an abstract continuation at
       panic's ENTRY, so no instruction of panic is fetched here
       memset -- already catalogued in iris/UCodeShK.v; the walk reuses
       [UkSh.wp_ksh_memset] across the [shp_code]/[shk_code] bridge
       atoi, chdir, close, dup, exec, exit, fork, fork1, fprintf, free, fstat,
       getcmd, getpid, gets, kill, link, main, memcmp, memcpy, memmove, mkdir,
       mknod, open, pause, pipe, printf, printint, putc, read, runcmd, sbrk,
       sbrklazy, seccomp, start, stat, strcmp, strcpy, sync, sys_sbrk, unlink,
       uptime, vprintf, wait, write -- not on the parser's path: the command
       loop and the ELF entry are UCodeShK.v's (SH lane stages 1-2), the
       allocator is stage 3's, and runcmd's tree walk with its fork/exec arms
       is stage 5's
       backcmd -- reached only from parseline's [peek(ps,es,'&')] loop --
       excluded by [ushp_no_symbols]
       listcmd -- reached only from parseline's [peek(ps,es,';')] arm --
       excluded by [ushp_no_symbols]
       parseblock -- reached only through [peek(ps,es,'(')] in parseexec, and a
       '(' is a symbol byte -- excluded by the walk's [ushp_no_symbols] premise
       on the line, so no instruction of it is ever fetched
       malloc -- stage 3's; stage 4 states its contract as the named local
       Hypothesis [ushp_malloc_ok], which crosses the call without fetching a
       single instruction of the allocator

   SH LANE STAGE 4: the recursive-descent PARSER and the lexer under it.
   [parsecmd] takes the line [main]'s blank scan left, measures it with
   [strlen], and calls [parseline] -> [parsepipe] -> [parseexec], each of
   which guards its own constructor with a [peek] for a symbol byte; the
   argument loop in [parseexec] calls [gettoken] once per token and records
   the token's two boundaries in the execcmd node [execcmd] allocated.
   [nulterminate] then writes a NUL at every recorded end, turning the
   token BOUNDARIES into the argv vector [exec] observes. [peek] and
   [gettoken] both run over the two static tables at 0x2000 (symbols) and
   0x2008 (whitespace) with [strchr]. WHAT IS NOT HERE, AND WHY IT IS NOT A
   GAP. [malloc] is stage 3's, and stage 4 states its contract as the one
   named local Hypothesis [ushp_malloc_ok] in iris/UkShParse.v -- the
   Hypothesis consumes the run at malloc's ENTRY pc and hands it back at
   the return address, so no instruction of malloc is ever fetched by this
   walk and a catalog fact about one would be a claim nothing reads.
   [memset], which [cmdalloc] calls, is already catalogued in UCodeShK.v
   and the walk reuses [UkSh.wp_ksh_memset] across the
   [shp_code]/[shk_code] bridge. So is [panic], which [cmdalloc] calls when
   [malloc] returns NULL: the walk stops at panic's ENTRY and hands the run
   to an abstract continuation.

   Every AST below was READ OFF the model -- [vm_compute] of the decoder at
   the U-mode reference state [dstateU] (base) / [decode_c_pure] under the
   misa.C gate (compressed) -- never guessed. In particular every
   jal/branch immediate is the decoder's POSITIVE residue, and a COMPRESSED
   branch or jump immediate counts HALFwords. The compressed words decode
   to the raw C_* constructors -- the expansion into ITYPE/STORE/...
   happens in [execute], not here.
 *)
From Stdlib Require Import ZArith Bool Lia List.
From stdpp Require Import gmap bitvector.definitions.
Require Import SailStdpp.ConcurrencyInterface SailStdpp.ConcurrencyInterfaceBuiltins SailStdpp.ConcurrencyInterfaceTypes SailStdpp.Operators_mwords.
Require Import SailStdpp.Base SailStdpp.TypeCasts SailStdpp.Values SailStdpp.MachineWord.
Require Import Riscv.rv64d_types Riscv.rv64d.
Require Import RiscvPtsto RiscvExtras.
Require Import UserPtTree.
Require Import WpDecodeBridge DecodeTotalU WpRvcBridge.
Require Import UmodeMem UmodeAbi.
From User Require ShInstrs ShData ShSyms.
Local Open Scope Z_scope.
Import Defs.

(* ===================================================================== *)
(* §0 The image and the layout premise.                                   *)
(* ===================================================================== *)

(* [M] contains the dumped text -- the generic image inclusion (UmodeAbi.v)
   at this program's text bytes.  An inclusion (not an equality), so a
   process image carrying rodata/bss/stack/argv on top still qualifies. *)
Definition shp_text_sub (M : gmap Z (bv 8)) : Prop :=
  uimg_sub ShInstrs.sh_bytes M.

(* ... and the dumped RODATA/data.  A string literal a program hands to
   [write] lives here, not in the text map, so the readable-window lemma
   below needs THIS inclusion. *)
Definition shp_data_sub (M : gmap Z (bv 8)) : Prop :=
  uimg_sub ShData.sh_data M.

(* ... and the two together, so a spec carries ONE image premise.  The
   per-pc [uinstr] facts below deliberately take only [shp_text_sub]: an
   instruction fetch never reads the data half. *)
Definition shp_img_sub (M : gmap Z (bv 8)) : Prop :=
  shp_text_sub M /\ shp_data_sub M.

Lemma shp_img_text (M : gmap Z (bv 8)) : shp_img_sub M -> shp_text_sub M.
Proof using . intros [ H _ ]. exact H. Qed.
Lemma shp_img_data (M : gmap Z (bv 8)) : shp_img_sub M -> shp_data_sub M.
Proof using . intros [ _ H ]. exact H. Qed.

(* ---- the KEY RANGE of each dumped map ------------------------------- *)
(* The bounds are COMPUTED from the dump (text keys stop at 0x1263, data keys
   at 0x200f) and rounded up to the next page, which is the shape the users of
   the fact want: [UmodeAbi.uM_only_img] asks exactly "the written window is
   disjoint from every key of [img]", and the windows a program writes are
   its stack, which starts at a page boundary above the image. *)

Lemma list_key_lt {A : Type} (L : list (Z * A)) (B k : Z) (b : A) :
  forallb (fun kv => Z.ltb (fst kv) B) L = true -> In (k, b) L -> k < B.
Proof using .
  induction L as [ | x xs IH ]; cbn [forallb In]; [ tauto | ].
  intros HF [ Hx | Hin ].
  - apply andb_prop in HF as [ H1 _ ]. subst x. cbn in H1.
    apply Z.ltb_lt in H1. exact H1.
  - apply andb_prop in HF as [ _ H2 ]. exact (IH H2 Hin).
Qed.

(* ...and the LOWER bound, which the same [forallb] decides.  [Hx] and
   every other page-range hypothesis is two-sided, so a key fact that
   only bounds above leaves [0 <= k] for [lia] to invent out of nothing. *)
Lemma list_key_nonneg {A : Type} (L : list (Z * A)) (k : Z) (b : A) :
  forallb (fun kv => Z.leb 0 (fst kv)) L = true -> In (k, b) L -> 0 <= k.
Proof using .
  induction L as [ | x xs IH ]; cbn [forallb In]; [ tauto | ].
  intros HF [ Hx | Hin ].
  - apply andb_prop in HF as [ H1 _ ]. subst x. cbn in H1.
    apply Z.leb_le in H1. exact H1.
  - apply andb_prop in HF as [ _ H2 ]. exact (IH H2 Hin).
Qed.

Lemma shp_bytes_key_lt (k : Z) (b : bv 8) :
  ShInstrs.sh_bytes !! k = Some b -> k < 8192.
Proof using .
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_lt _ 8192 k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma shp_bytes_key_nonneg (k : Z) (b : bv 8) :
  ShInstrs.sh_bytes !! k = Some b -> 0 <= k.
Proof using .
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_nonneg _ k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma shp_data_key_lt (k : Z) (b : bv 8) :
  ShData.sh_data !! k = Some b -> k < 12288.
Proof using .
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_lt _ 12288 k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma shp_data_key_nonneg (k : Z) (b : bv 8) :
  ShData.sh_data !! k = Some b -> 0 <= k.
Proof using .
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_nonneg _ k b _ Hk).
  vm_compute. reflexivity.
Qed.

(* The vpn of an address IS the vpn of its page base.  This is the
   arithmetic the two projections below need, and having it ONCE is what
   lets a per-pc proof state no svpn identity of its own -- UCodeEcho.v
   could do that identification with a [vm_compute] per instance only
   because its whole image was page 0. *)
Lemma shp_svpn_page (a : Z) :
  0 <= a < 274877906944 ->
  svpn_of (mword_of_int a : mword 64)
    = svpn_of (mword_of_int (4096 * (a / 4096)) : mword 64).
Proof using .
  intros [ Hlo Hhi ].
  assert (Hq : 0 <= 4096 * (a / 4096) <= a).
  { split.
    - apply Z.mul_nonneg_nonneg; [ lia | apply Z.div_pos; lia ].
    - apply Z.mul_div_le; lia. }
  apply bv_eq.
  rewrite (svpn_of_unsigned_lo (mword_of_int a : mword 64))
    by (rewrite uint_unsigned, moi64_small; lia).
  rewrite (svpn_of_unsigned_lo (mword_of_int (4096 * (a / 4096)) : mword 64))
    by (rewrite uint_unsigned, moi64_small; lia).
  rewrite !uint_unsigned, !moi64_small by lia.
  rewrite !Z.shiftr_div_pow2 by lia.
  change (2 ^ 12) with 4096.
  rewrite (Z.mul_comm 4096 (a / 4096)), Z.div_mul by lia. reflexivity.
Qed.

(* The pure page-table premise: each of the 2 page(s) of the executable
   segment is mapped with a leaf that permits instruction FETCH and a user
   data LOAD.  Quantified over the page INDEX rather than one field per
   page, so the record does not change shape when a program grows; page [i]
   is user va [4096*i], because a user program is linked at 0
   (user/user.ld).  The load half is what makes a .rodata string sharing a
   text page a legal [write] buffer. *)
Record shp_text_layout (pt : uptd) : Prop := ShpTextLayout {
  stl_pg : forall i : Z, 0 <= i < 2 ->
    exists w : mword 64,
      ud_um pt !! svpn_of (mword_of_int (4096 * i) : mword 64) = Some w /\
      uleaf_ok (InstructionFetch tt) w /\ uleaf_ok (Load Data) w
}.

(* the fetch projection, in exactly the shape [UmodeMem.uva_fetch_leaf]
   wants -- it takes the page index from the address itself *)
Lemma shp_text_layout_fetch (pt : uptd) (off : Z) :
  shp_text_layout pt -> 0 <= off < 8192 ->
  uva_fetch_leaf pt (mword_of_int off).
Proof using .
  intros [ Hpg ] Hoff.
  destruct (Hpg (off / 4096)
              ltac:(split; [ apply Z.div_pos; lia
                           | apply Z.div_lt_upper_bound; lia ]))
    as (w & Hl & Hok & _).
  exists w. rewrite (shp_svpn_page off ltac:(lia)). split; assumption.
Qed.

(* the same leaf, in the shape [UmodeAbi.uv_rd]'s [urd_leaf] field wants *)
Lemma shp_text_layout_load (pt : uptd) (a : Z) :
  shp_text_layout pt -> 0 <= a < 8192 ->
  exists w : mword 64,
    ud_um pt !! svpn_of (mword_of_int a : mword 64) = Some w /\
    uleaf_ok (Load Data) w.
Proof using .
  intros [ Hpg ] Ha.
  destruct (Hpg (a / 4096)
              ltac:(split; [ apply Z.div_pos; lia
                           | apply Z.div_lt_upper_bound; lia ]))
    as (w & Hl & _ & Hok).
  exists w. rewrite (shp_svpn_page a ltac:(lia)). split; assumption.
Qed.

(* ONE readable byte of the loaded data image, on a text page -- the
   address is a parameter, so each string literal a program hands to
   [write] costs one line at the call site. *)
Lemma shp_rodata_rd1 (pt : uptd) (M : gmap Z (bv 8)) (a : Z) (b : bv 8) :
  shp_text_layout pt -> shp_data_sub M ->
  0 <= a < 8192 ->
  ShData.sh_data !! a = Some b ->
  uv_rd pt M a 1.
Proof using .
  intros Hl Hsub Ha Hb. constructor.
  - lia.
  - lia.
  - change (2 ^ 38) with 274877906944. lia.
  - intros j Hj. assert (Hj0 : j = 0) by lia. subst j.
    rewrite Z.add_0_r. exact (shp_text_layout_load pt a Hl Ha).
  - intros j Hj. assert (Hj0 : j = 0) by lia. subst j.
    rewrite Z.add_0_r. exists b. exact (Hsub a b Hb).
Qed.

(* the addresses this file is about, as the dumper named them *)
Lemma shp_syms_pins :
  ShSyms.parsecmd = 0x84a /\
  ShSyms.parseline = 0x6be /\
  ShSyms.parsepipe = 0x65e /\
  ShSyms.parseexec = 0x56c /\
  ShSyms.parseredirs = 0x488 /\
  ShSyms.nulterminate = 0x7ca /\
  ShSyms.peek = 0x424 /\
  ShSyms.gettoken = 0x2ec /\
  ShSyms.cmdalloc = 0x1d2 /\
  ShSyms.execcmd = 0x20a /\
  ShSyms.redircmd = 0x226 /\
  ShSyms.pipecmd = 0x272 /\
  ShSyms.strlen = 0xa0c /\
  ShSyms.strchr = 0xa5e.
Proof using .
  unfold ShSyms.parsecmd,
         ShSyms.parseline,
         ShSyms.parsepipe,
         ShSyms.parseexec,
         ShSyms.parseredirs,
         ShSyms.nulterminate,
         ShSyms.peek,
         ShSyms.gettoken,
         ShSyms.cmdalloc,
         ShSyms.execcmd,
         ShSyms.redircmd,
         ShSyms.pipecmd,
         ShSyms.strlen,
         ShSyms.strchr.
  split_and!; reflexivity.
Qed.

(* ===================================================================== *)
(* §1 Per-WORD decode facts.                                              *)
(* ===================================================================== *)

(* One lemma per DISTINCT word (379 of them for 632 instructions), reused
   at every pc where that word occurs.

   Base words: the concrete-state bridge at [dstateU] (WpDecodeBridge),
   transported to any state agreeing with it on the U-mode decode read set
   [D_u] -- exactly the [udecode_base] shape [uinstr] wants. The closing
   step descends the AST with [f_equal] and finishes each bitvector leaf
   with [bv_eq] (a bare [reflexivity] would have to match well-formedness
   proof terms).

   Compressed words: [rvc_oneshot] under the misa.C premise. *)

Ltac udec_base_bridge :=
  let s := fresh "s" in let Hag := fresh "Hag" in
  intros s Hag;
  apply (decode_state_bridge D_u _ dstateU);
  [ exact Hag
  | vm_compute; reflexivity
  | vm_compute; repeat first [ reflexivity | (apply bv_eq; vm_compute; reflexivity) | f_equal ] ].

Ltac udec_rvc_oneshot :=
  let s := fresh "s" in let Hm := fresh "Hm" in intros s Hm; rvc_oneshot s Hm.

(* ---- compressed ---- *)
